/**
 * hex 색상 문자열을 rgba() 문자열로 변환해요.
 *
 * 3, 4, 6, 8자리 hex를 지원하고 앞의 '#'은 있어도 없어도 돼요.
 * 4, 8자리 hex의 알파 값보다 두 번째 인자로 넘긴 alpha가 우선해요.
 *
 * @example
 * hexToRgba('#3182f6'); // 'rgba(49, 130, 246, 1)'
 * hexToRgba('#3182f6', 0.16); // 'rgba(49, 130, 246, 0.16)'
 * hexToRgba('#11223344'); // 'rgba(17, 34, 51, 0.27)'
 */
export declare function hexToRgba(hex: string, alpha?: number | string): string;
